export const STORAGE_KEY = 'opscotch-monitor.connector-config.v1';
const empty = () => ({ version: 3, activeConnector: 'polling', polling: { url: '' }, metricsStore: { apiUrl: '', authorization: '', metricNames: '', dimensions: '' } });
export function loadConnectorConfig(storage = window.localStorage) { const fallback = empty(); try { const stored = JSON.parse(storage.getItem(STORAGE_KEY)); if (stored && stored.version === 3) return { ...fallback, ...stored, activeConnector: stored.activeConnector === 'metricsStore' ? 'metricsStore' : 'polling', polling: { ...fallback.polling, ...stored.polling }, metricsStore: { ...fallback.metricsStore, ...stored.metricsStore } }; if (stored && stored.version === 2) { const migrated = { ...fallback, activeConnector: stored.activeConnector === 'metricsStore' ? 'metricsStore' : 'polling', polling: { ...fallback.polling, ...stored.polling }, metricsStore: { ...fallback.metricsStore, ...stored.metricsStore } }; saveConnectorConfig(migrated, storage); return migrated; } if (stored && stored.version === 1) { const apiUrl = /^https?:\/\//i.test(stored.live?.url || '') ? stored.live.url : ''; const migrated = { ...fallback, activeConnector: stored.activeConnector === 'live' ? 'metricsStore' : 'polling', polling: { ...fallback.polling, ...stored.polling }, metricsStore: { ...fallback.metricsStore, apiUrl } }; saveConnectorConfig(migrated, storage); return migrated; } const legacyUrl = storage.getItem('url'); if (legacyUrl) return { ...fallback, polling: { url: legacyUrl } }; } catch (_) {} return fallback; }
export function saveConnectorConfig(config, storage = window.localStorage) { const normalized = { ...empty(), ...config, activeConnector: config.activeConnector === 'metricsStore' ? 'metricsStore' : 'polling', polling: { url: (config.polling?.url || '').trim() }, metricsStore: { ...empty().metricsStore, ...config.metricsStore, apiUrl: (config.metricsStore?.apiUrl || '').trim(), authorization: (config.metricsStore?.authorization || '').trim() } }; storage.setItem(STORAGE_KEY, JSON.stringify(normalized)); return normalized; }
